import{_ as o,C as t,c,o as a,aa as r,G as l}from"./chunks/framework.Cn7WEiMX.js";const y=JSON.parse('{"title":"命令列表","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/setup/base-plugin-settings/commands.md","filePath":"wiki/Dynmap/setup/base-plugin-settings/commands.md"}'),g={name:"wiki/Dynmap/setup/base-plugin-settings/commands.md"};function m(n,e,s,p,u,k){const d=t("NolebaseGitContributors"),i=t("NolebaseGitChangelog");return a(),c("div",null,[e[0]||(e[0]=r('<h1 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to &quot;命令列表&quot;">​</a></h1> <h2 id="玩家显示控制" tabindex="-1">玩家显示控制 <a class="header-anchor" href="#玩家显示控制" aria-label="Permalink to &quot;玩家显示控制&quot;">​</a></h2> <ul><li><code>/dynmap hide</code>：将玩家从地图上隐去。</li> <li><code>/dynmap hide &lt;玩家名称&gt;</code>：将指定玩家从地图上隐去。</li> <li><code>/dynmap show</code>：将玩家重新显示在地图上。</li> <li><code>/dynmap show &lt;玩家名称&gt;</code>：将指定玩家重新显示在地图上。</li></ul> <h2 id="渲染相关" tabindex="-1">渲染相关 <a class="header-anchor" href="#渲染相关" aria-label="Permalink to &quot;渲染相关&quot;">​</a></h2> <ul><li><code>/dynmap render</code>：渲染你所处区块的图块。</li> <li><code>/dynmap fullrender</code>：尝试从你所处的位置开始渲染整个世界的地图（若为控制台输入，则从世界中心开始）。</li> <li><code>/dynmap fullrender &lt;世界名称&gt;</code>：尝试从世界中心开始渲染整个世界的地图。</li> <li><code>/dynmap fullrender &lt;世界名称&gt;:surface</code>：尝试从指定世界的中心开始渲染整个世界的地表地图。</li> <li><code>/dynmap fullrender resume &lt;世界名称&gt;</code>：继续地图渲染任务。自动跳过渲染完毕的图块。</li> <li><code>/dynmap fullrender resume &lt;世界名称&gt;:&lt;地图类型&gt;</code>：继续地图渲染任务。自动跳过渲染完毕的图块。</li> <li><code>/dynmap radiusrender &lt;半径&gt;</code>：尝试渲染至少指定半径内的方块区域，以你所处的位置为中心。</li> <li><code>/dynmap radiusrender &lt;半径&gt; &lt;地图类型&gt;</code>：尝试渲染至少指定半径内的方块区域，以你所处的位置为中心，以当前地图类型为基础。</li> <li><code>/dynmap radiusrender &lt;世界名称&gt; &lt;X 轴坐标&gt; &lt;Z 轴坐标&gt; &lt;半径&gt;</code>：以指定世界及位置为中心，渲染一定范围内的区域。</li> <li><code>/dynmap updaterender</code>：尝试渲染被标记为需更新的图块，从当前位置开始，逐渐覆盖整个地图。触及地图边缘或不需要更新的图块后停止。</li> <li><code>/dynmap updaterender &lt;地图类型&gt;</code>：尝试渲染指定类型地图中被标记为需更新的图块，从当前位置开始，逐渐覆盖整个地图。触及地图边缘或不需要更新的图块后停止。</li> <li><code>/dynmap updaterender &lt;世界名称&gt; &lt;X 轴坐标&gt; &lt;Z 轴坐标&gt;</code>：尝试渲染被标记为需更新的图块，从指定世界的位置开始，逐渐覆盖整个地图。触及地图边缘或不需要更新的图块后停止。</li> <li><code>/dynmap updaterender &lt;世界名称&gt; &lt;X 轴坐标&gt; &lt;Z 轴坐标&gt; &lt;半径&gt;</code>：尝试渲染被标记为需更新的图块，从指定世界的位置开始，逐渐覆盖半径内区域。触及地图边缘或不需要更新的图块后停止。</li> <li><code>/dynmap cancelrender &lt;世界名称&gt;</code>：停止指定世界中正在进行的完全渲染或范围渲染任务。</li> <li><code>/dynmap purgequeue</code>：清除图块更新队伍。</li> <li><code>/dynmap purgeworld &lt;世界名称&gt;</code>：清除指定世界的所有地图文件。</li> <li><code>/dynmap purgemap &lt;世界名称&gt; &lt;地图类型&gt;</code>：清除指定世界指定类型的地图文件。</li> <li><code>/dynmap pause all</code>：停止所有地图渲染任务（包括地图更新及完整/范围渲染任务）</li> <li><code>/dynmap pause none</code>：继续所有地图渲染任务</li> <li><code>/dynmap quiet</code>：切换渲染消息</li></ul> <h2 id="统计数据相关" tabindex="-1">统计数据相关 <a class="header-anchor" href="#统计数据相关" aria-label="Permalink to &quot;统计数据相关&quot;">​</a></h2> <ul><li><code>/dynmap stats</code>：显示所有世界不同类型地图的渲染统计数据。</li> <li><code>/dynmap stats &lt;世界名称&gt;</code>：显示指定世界不同类型地图的渲染统计数据。</li> <li><code>/dynmap triggerstats</code>：显示所有世界的触发渲染统计数据。</li> <li><code>/dynmap resetstats</code>：重置所有世界不同类型地图的渲染统计数据。</li> <li><code>/dynmap resetstats &lt;世界名称&gt;</code>：重置指定世界不同类型地图的渲染数据。</li></ul> <h2 id="地图标记相关" tabindex="-1">地图标记相关 <a class="header-anchor" href="#地图标记相关" aria-label="Permalink to &quot;地图标记相关&quot;">​</a></h2> <p>仅在启用了“地图标记”组件（需 0.22 版本后）后才可使用这些命令。</p> <ul><li><code>/dmarker add &lt;标签&gt; icon:&lt;图标&gt; set:&lt;设置 ID&gt;</code>：在玩家当前位置添加新标记点，带有指定标签及可选图标，还可设置标记点组。</li> <li><code>/dmarker add id:&lt;id&gt; &lt;标签&gt; icon:&lt;图标&gt; set:&lt;设置 ID&gt;</code>：在玩家当前位置添加新标记点，带有指定 ID、标签及可选图标，还可设置标记点组。</li> <li><code>/dmarker add id:&lt;id&gt; &lt;标签&gt; icon:&lt;图标&gt; set:&lt;设置 ID&gt; x:&lt;x 轴坐标&gt; y:&lt;y 轴坐标&gt; z:&lt;z 轴坐标&gt; world:&lt;世界名称&gt;</code>：在世界的指定位置添加新标记点，带有指定 ID、标签及可选图标，还可设置标记点组。</li> <li><code>/dmarker movehere &lt;标签&gt;</code>：将对应标签的标记点移动到玩家当前的位置。</li> <li><code>/dmarker movehere id:&lt;id&gt;</code>：将对应 ID 的标记点移动到玩家当前的位置。</li> <li><code>/dmarker update &lt;标签&gt; icon:&lt;新图标&gt; newlabel:&lt;新标签&gt;</code>：修改对应标签的标记点图标，并重命名其标签。</li> <li><code>/dmarker update id:&lt;id&gt; icon:&lt;新图标&gt; newlabel:&lt;新标签&gt;</code>：修改对应 ID 的标记点图标，并重命名其标签。</li> <li><code>/dmarker delete &lt;标签&gt;</code>：删除对应标签的标记点。</li> <li><code>/dmarker delete id:&lt;id&gt;</code>：删除对应 ID 的标记点。</li> <li><code>/dmarker list</code>：列出默认标记点组中的所有标记点。</li> <li><code>/dmarker list set:&lt;设置 ID&gt;</code>：列出指定标记点组中的所有标记点。</li> <li><code>/dmarker icons</code>：列出标记点使用的所有图标。</li> <li><code>/dmarker addset &lt;标签&gt; hide:&lt;默认隐藏&gt; prio:&lt;优先级&gt; minzoom:&lt;最小缩放&gt;</code>：新建标记点组，并设置指定标签（ID = 标签）</li> <li><code>/dmarker addset id:&lt;id&gt; &lt;标签&gt; hide:&lt;默认隐藏&gt; prio:&lt;优先级&gt; minzoom:&lt;最小缩放&gt;</code>：新建标记点组，并设置指定 ID 与标签</li> <li><code>/dmarker updateset &lt;标签&gt; newlabel:&lt;new-label&gt; hide:&lt;默认隐藏&gt; prio:&lt;优先级&gt; minzoom:&lt;最小缩放&gt;</code>：更新指定标签的标记点组（ID = 标签）</li> <li><code>/dmarker updateset id:&lt;id&gt; newlabel:&lt;new-label&gt; hide:&lt;默认隐藏&gt; prio:&lt;优先级&gt; minzoom:&lt;最小缩放&gt;</code>：更新指定 ID 的标记点组</li> <li><code>/dmarker deleteset &lt;标签&gt;</code>：删除指定标签的标记点组。</li> <li><code>/dmarker deleteset id:&lt;id&gt;</code>：删除指定 ID 的标记点组。</li> <li><code>/dmarker listsets</code>：列出所有标记点。</li> <li><code>/dmarker addicon id:&lt;id&gt; &lt;标签&gt; file:&quot;文件名称&quot;</code>：从指定文件（路径相对于服务器所在根目录，文件内容会被复制）安装新图标，设置 ID 与标签。</li> <li><code>/dmarker updateicon id:&lt;id&gt; newlabel:&lt;标签&gt; file:&quot;文件名称&quot;</code>：从指定文件更新图标，以读取内容替代现有设置。</li> <li><code>/dmarker deleteicon id:&lt;id&gt;</code>：删除指定 ID 的图标。</li> <li><code>/dmarker addcorner</code>：将当前位置作为角点添加至角点列表。</li> <li><code>/dmarker addcorner &lt;x&gt; &lt;y&gt; &lt;z&gt; &lt;世界名称&gt;</code>：将指定位置作为角点添加至角点列表。</li> <li><code>/dmarker clearcorners</code>：清理角点列表。</li> <li><code>/dmarker addarea &lt;标签&gt;</code>：通过角点列表新建指定标签的区域。</li> <li><code>/dmarker addarea id:&lt;id&gt; &lt;标签&gt;</code>：通过角点列表新建指定 ID 的区域。</li> <li><code>/dmarker deletearea &lt;标签&gt;</code>：删除指定标签对应的区域。</li> <li><code>/dmarker deletearea id:&lt;id&gt; &lt;标签&gt;</code>：删除指定 ID 对应的区域。</li> <li><code>/dmarker listareas</code>：列出所有区域。</li> <li><code>/dmarker updatearea &lt;标签&gt; &lt;参数&gt;:&lt;值&gt; ...</code>：更新指定标签对应区域的属性。</li> <li><code>/dmarker updatearea &lt;id&gt; &lt;参数&gt;:&lt;值&gt; ...</code>：更新指定 ID 对应区域的属性。</li> <li><code>/dmarker updatearea &lt;id&gt; label:&lt;标签&gt; newlabel:&lt;新标签&gt;</code>：更新指定 ID 的区域标记点标签。</li> <li><code>/dmarker addcircle &lt;标签&gt;</code>：通过角点列表新建指定标签的圆形区域。</li> <li><code>/dmarker addcircle id:&lt;id&gt; &lt;标签&gt;</code>：通过角点列表新建指定 ID 的圆形区域。</li> <li><code>/dmarker deletecircle &lt;标签&gt;</code>：删除指定标签对应的圆形区域。</li> <li><code>/dmarker deletecircle id:&lt;id&gt; &lt;标签&gt;</code>：删除指定 ID 对应的圆形区域。</li> <li><code>/dmarker listcircles</code>：列出所有圆形区域。</li> <li><code>/dmarker updatecircle &lt;标签&gt; &lt;参数&gt;:&lt;值&gt; ...</code>：更新指定标签对应圆形区域的属性。</li> <li><code>/dmarker updatecircle &lt;id&gt; &lt;参数&gt;:&lt;值&gt; ...</code>：更新指定 ID 对应圆形区域的属性。</li> <li><code>/dmarker updatecircle &lt;id&gt; label:&lt;标签&gt; newlabel:&lt;新标签&gt;</code>：更新指定 ID 的圆形区域标记点标签。</li> <li><code>/dmarker addline &lt;标签&gt;</code>：通过角点列表新建指定标签的线形区域。</li> <li><code>/dmarker addline id:&lt;id&gt; &lt;标签&gt;</code>：通过角点列表新建指定 ID 的线形区域。</li> <li><code>/dmarker deleteline &lt;标签&gt;</code>：删除指定标签对应的线形区域。</li> <li><code>/dmarker deleteline id:&lt;id&gt; &lt;标签&gt;</code>：删除指定 ID 对应的线形区域。</li> <li><code>/dmarker listlines</code>：列出所有线形区域。</li> <li><code>/dmarker updateline &lt;标签&gt; &lt;参数&gt;:&lt;值&gt; ...</code>：更新指定标签对应线形区域的属性。</li> <li><code>/dmarker updateline id:&lt;id&gt; &lt;参数&gt;:&lt;值&gt; ...</code>：更新指定 ID 对应线形区域的属性。</li> <li><code>/dmarker appenddesc id:&lt;id&gt; set:&lt;设置 ID&gt; desc:&quot;&lt;标记描述&gt;&quot;</code>：更新指定 ID 的线形区域标记点标签。</li> <li><code>/dmarker resetdesc id:&lt;id&gt; set:&lt;设置 ID&gt;</code>：重置标记点的描述。</li></ul> <h2 id="地图-世界配置命令" tabindex="-1">地图/世界配置命令 <a class="header-anchor" href="#地图-世界配置命令" aria-label="Permalink to &quot;地图/世界配置命令&quot;">​</a></h2> <ul><li><code>/dmap worldlist</code>：列出所有配置的世界（不论启用或禁用）</li> <li><code>/dmap worldset &lt;世界名称&gt; enabled:&lt;true|false&gt;</code>：将指定世界的配置开启或关闭。</li> <li><code>/dmap worldset &lt;世界名称&gt; center:&lt;x/y/z|here|default&gt;</code>：设置指定世界的地图中心。</li> <li><code>/dmap worldset &lt;世界名称&gt; extrazoomout:&lt;数字&gt;</code>：设置指定世界的额外缩放等级。</li> <li><code>/dmap worldset &lt;世界名称&gt; title:&lt;标签&gt;</code>：设置指定世界的标题。</li> <li><code>/dmap worldset &lt;世界名称&gt; sendposition:&lt;true|false&gt; sendhealth:&lt;true|false&gt;</code>：设置指定世界的 send-position 和/或 send-health 标志。</li> <li><code>/dmap worldset &lt;世界名称&gt; order:&lt;数字&gt;</code>：将指定世界的位置移动到世界列表中的指定位置。</li> <li><code>/dmap worldreset &lt;世界名称&gt;</code>：将指定世界重置为默认配置。</li> <li><code>/dmap worldreset &lt;世界名称&gt; &lt;模板名称&gt;</code>：将指定世界重置为指定的默认配置。</li> <li><code>/dmap maplist &lt;世界名称&gt;</code>：列出指定世界所有类型的地图信息。</li> <li><code>/dmap mapdelete &lt;世界名称&gt;:&lt;地图类型&gt;</code>：删除指定世界的指定类型地图。</li> <li><code>/dmap mapadd &lt;世界名称&gt;:&lt;地图类型&gt; &lt;属性:值,属性:值,...&gt;</code>：新建指定世界的指定类型地图，可额外设置属性（兼容所有 <code>mapset</code> 命令中能使用的参数）。</li> <li><code>/dmap mapset &lt;世界名称&gt;:&lt;地图类型&gt; order:&lt;数字&gt;</code>：将指定世界指定类型地图的位置移动到地图列表中的指定位置。</li> <li><code>/dmap mapset &lt;世界名称&gt;:&lt;地图类型&gt; prefix:&lt;前缀&gt;</code>：设置指定世界指定类型地图的文件名称前缀。</li> <li><code>/dmap mapset &lt;世界名称&gt;:&lt;地图类型&gt; title:&lt;标签&gt;</code>：设置指定世界指定类型地图的标题。</li> <li><code>/dmap mapset &lt;世界名称&gt;:&lt;地图类型&gt; icon:&lt;图标文件&gt;</code>：设置指定世界指定类型地图的标题。（相对于 <code>webpath</code> 文件夹）。</li> <li><code>/dmap mapset &lt;世界名称&gt;:&lt;地图类型&gt; mapzoomin:&lt;数字&gt;</code>：设置指定世界指定类型地图的缩放等级。</li> <li><code>/dmap mapset &lt;世界名称&gt;:&lt;地图类型&gt; perspective:&lt;角度&gt; shader:&lt;阴影&gt; lighting:&lt;光照&gt;</code>：设置指定世界指定类型地图的角度、阴影及光照。</li> <li><code>/dmap mapset &lt;世界名称&gt;:&lt;地图类型&gt; img-format:&lt;格式&gt;</code>：设置指定世界指定类型地图的图片格式（<code>png</code>、<code>jpg</code>、<code>jpg-q90</code>、<code>jpg-q95</code> 等）。</li> <li><code>/dmap perspectivelist</code>：列出所有设定的角度。</li> <li><code>/dmap shaderlist</code>：列出所有设定的阴影。</li> <li><code>/dmap lightinglist</code>：列出所有设定的光照。</li> <li><code>/dmap worldgetlimits &lt;世界名称&gt;</code>：返回世界可见性及隐藏限制，以及显示“限制类型”的列表，和形状属性设置。</li> <li><code>/dmap worldaddlimit &lt;世界名称&gt; corner1:&lt;x1&gt;/&lt;z1&gt; corner2:&lt;x2&gt;/&lt;z2&gt;</code>：新建位置为 <code>x1,z1</code> 到 <code>x2,z2</code> 的矩形视野限制。添加数量不限。</li> <li><code>/dmap worldaddlimit &lt;世界名称&gt; corner1:&lt;x1&gt;/&lt;z1&gt; corner2:&lt;x2&gt;/&lt;z2&gt; limittype:hidden</code>：新建位置为 <code>x1,z1</code> 到 <code>x2,z2</code> 的矩形视野隐藏限制。添加数量不限。与普通视野限制效果相反。</li> <li><code>/dmap worldaddlimit &lt;世界名称&gt; type:round center:&lt;x&gt;/&lt;z&gt; radius:&lt;半径&gt;</code>：新建圆心为 <code>x,z</code> 的圆形视野隐藏限制。添加数量不限。</li> <li><code>/dmap worldremovelimit &lt;世界名称&gt; &lt;编号&gt;</code>：删除指定编号的视野限制（可在 <code>/dmap worldgetlimits</code> 列表中浏览）。</li> <li><code>/dmap worldaddlimit &lt;世界名称&gt; style:&lt;air|stone|ocean&gt;</code>：默认为 <code>stone</code>（石头），若需要类似区块被直接“裁剪”的效果（例如，若需要在世界边界外生成区块，保留建筑结构等内容的完整性），请将其设置为 <code>air</code>（空气）。</li></ul> <h2 id="杂项命令" tabindex="-1">杂项命令 <a class="header-anchor" href="#杂项命令" aria-label="Permalink to &quot;杂项命令&quot;">​</a></h2> <p>各种各样的其他命令。</p> <ul><li><code>/dynmap sendtoweb message ...</code>：向网页客户端发送消息。</li> <li><code>/dynmap ids-for-ip &lt;IP 地址&gt;</code>：列出使用过指定 IP 地址登录的玩家列表（按时间从早到晚排序）</li> <li><code>/dynmap ips-for-id &lt;玩家名称&gt;</code>：列出使用过指定玩家名称登录的 IP 列表（按时间从早到晚排序）</li> <li><code>/dynmap add-id-for-ip &lt;玩家名称&gt; &lt;IP 地址&gt;</code>：对指定 IP 地址添加玩家名称。</li> <li><code>/dynmap del-id-for-ip &lt;玩家名称&gt; &lt;IP 地址&gt;</code>：移除指定 IP 地址使用过的玩家名称。</li> <li><code>/dynmap webregister</code>：开始注册网页地图账号。</li> <li><code>/dynmap webregister &lt;玩家名称&gt;</code>：为其他玩家注册网页地图账号。</li> <li><code>/dynmap url</code>：若有，显示设置的 publicURL。</li></ul> ',30)),l(d),l(i)])}const b=o(g,[["render",m]]);export{y as __pageData,b as default};
